#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int calculate_unique_score_combinations(int n) {
    vector<vector<int>> scores(n);

    // Generate all possible combinations of scores for the 5 students
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 7; ++j) {
            for (int k = 0; k <= j; ++k) {
                for (int l = 0; l <= k; ++l) {
                    scores[i] = {j, k, l};
                    break; // Just to get the unique combination, not all 216 combinations are required
                }
            }
        }
    }

    sort(scores.begin(), scores.end(), [](const vector<int>& v1, const vector<int>& v2) {
        return v1[0] < v2[0] || (v1[0] == v2[0] && v1[1] < v2[1]) || (v1[0] == v2[0] && v1[1] == v2[1] && v1[2] < v2[2]);
    });

    int unique_combinations = 0;
    for (int i = 0; i < n; ++i) {
        if (i == 0 || scores[i][0] != scores[i-1][0] || scores[i][1] != scores[i-1][1] || scores[i][2] != scores[i-1][2]) {
            unique_combinations++;
        }
    }

    return unique_combinations;
}

int main() {
    int n;
    cin >> n;
    // Read the scores for each of the 'n' pairs of students
    // We are not generating the actual scores, but rather counting unique combinations of scores meeting the condition
    // This can be optimized further dynamically, but for now, this will simulate the process
    int max_students = calculate_unique_score_combinations(n);
    cout << max_students << endl;
    return 0;
}


