#import "CustomCollectionViewCell.h"
#import "CustomCollectionViewViewController.h"
#import "PageCurlLayout.h"
#import "PageCurlFlowLayout.h"

@interface CustomCollectionViewViewController () <UICollectionViewDelegate, UICollectionViewDataSource, UICollectionViewDelegateFlowLayout>

@property (nonatomic, strong) UICollectionViewFlowLayout *collectionViewLayout;
@property (nonatomic, strong) UICollectionView *collectionView;

@end

@implementation CustomCollectionViewViewController

- (void)viewDidLoad {
    [super viewDidLoad];

    // Create the page curl layout
    PageCurlLayout *pageCurlLayout = [[PageCurlLayout alloc] init];
    pageCurlLayout.spacing = 10;
    pageCurlLayout.curlWidth = 50;

    // Set the layout
    self.collectionViewLayout = pageCurlLayout;
    self.collectionView = [[UICollectionView alloc] initWithFrame:self.view.bounds collectionViewLayout:self.collectionViewLayout];

    // Register the view cells
    [self.collectionView registerClass:[CustomCollectionViewCell class] forCellWithReuseIdentifier:@"CustomCollectionViewCell"];

    // Set the data source and delegate
    self.collectionView.dataSource = self;
    self.collectionView.delegate = self;

    // Add the collection view to the view
    [self.view addSubview:self.collectionView];
    self.collectionView.backgroundColor = [UIColor whiteColor];
}

#pragma mark - UICollectionViewDataSource

- (NSInteger)numberOfSectionsInCollectionView:(UICollectionView *)collectionView {
    return 1;
}

- (NSInteger)collectionView:(UICollectionView *)collectionView numberOfItemsInSection:(NSInteger)section {
    return kNumberOfItemsPerSection;
}

- (UICollectionViewCell *)collectionView:(UICollectionView *)collectionView cellForItemAtIndexPath:(NSIndexPath *)indexPath {
    CustomCollectionViewCell *cell = [collectionView dequeueReusableCellWithReuseIdentifier:@"CustomCollectionViewCell" forIndexPath:indexPath];

    // Configure the cell
    cell.titleLabel.text = [NSString stringWithFormat:@"%ld", indexPath.item];

    // Return the cell
    return cell;
}

- (CGSize)collectionView:(UICollectionView *)collectionView layout:(UICollectionViewLayout *)collectionViewLayout sizeForItemAtIndexPath:(NSIndexPath *)indexPath {
    return CGSizeMake(floor((collectionView.frame.size.width - kSpacing * 2) / kInnerPages), kItemSize.height);
}

#pragma mark - UICollectionViewDelegateFlowLayout

- (UICollectionViewFlowLayout *)collectionView:(UICollectionView *)collectionView layout:(UICollectionViewLayout *)collectionViewLayout referenceSizeForHeaderInSection:(NSInteger)section {
    UILabel *label = [[UILabel alloc] init];
    label.text = @"Header";

    CGSize constraintSize = CGSizeMake(MINFLOAT, label.size.height);
    CGSize optimalSize = [label sizeThatFits:constraintSize];

    CGSize size = CGSizeMake(kItemSize.width, optimalSize.height);

    return size;
}

- (UICollectionViewFlowLayout *)collectionView:(UICollectionView *)collectionView layout:(UICollectionViewLayout *)collectionViewLayout referenceSizeForFooterInSection:(NSInteger)section {
    UILabel *label = [[UILabel alloc] init];
    label.text = @"Footer";

    CGSize constraintSize = CGSizeMake(MINFLOAT, label.size.height);
    CGSize optimalSize = [label sizeThatFits:constraintSize];

    CGSize size = CGSizeMake(kItemSize.width, optimalSize.height);

    return size;
}

@end

